def extract(source,start,end):return source[source.index(start):source.index(end,source.index(start))].strip()
learning=[('Read the actual Python file','The starting utils.py matches the presentation: empty numbers divide by zero and a None user cannot be indexed.'),('Describe the repair with a prompt','query() starts one SDK workflow. The prompt describes the goal; the model chooses the tool requests.'),('Separate availability and approval','tools enables only Read, Edit and Glob. allowedTools pre-approves them; permissionMode acceptEdits approves editing operations.'),('Watch real tool execution','The SDK reads and edits a disposable utils.py copy. The host does not send a prewritten patch or implement a manual tool loop.'),('Print selected messages','Observe assistant text, tool names and the final SDK result. These are progress and outcome signals, not a hidden reasoning trace.'),('Verify changes independently','Compare before/after code and four host-run Python checks. SDK success alone does not prove the repair is correct.')]
setup='mkdir my-agent\ncd my-agent\nnpm init -y\nnpm pkg set type=module\nnpm install @anthropic-ai/claude-agent-sdk\nnpm install --save-dev tsx'
clone='git clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson03-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson03-app\nnpm ci'
shell='$env:ANTHROPIC_API_KEY = "your_api_key"\nnpm run sample'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3103\nPYTHON_BIN=python'
walk=[('01','Start with the two crash bugs','fixtures/utils.py','This is the presentation’s exact starting file. The normal calls work; the empty-list and None-user cases crash. The fixture stays unchanged while each run resets a separate working copy.',buggy,'python'),('02','Reset only the disposable working copy','src/agent.ts','Every submitted run copies the buggy fixture to .runtime/bugfix-workspace/utils.py. The app never replaces its fixture with a prewritten fix. This makes classroom repetitions comparable.',extract(agent,'export async function ensureWorkspace','export async function verifyFile'),'typescript'),('03','Choose tools and edit approvals','src/agent.ts','tools sets availability; allowedTools sets automatic approvals. acceptEdits is the lesson’s edit permission mode. Additional path checks limit this host’s file operations to the one demo target. No Bash or external search is enabled.',extract(agent,'export function lessonOptions','export function validatePrompt'),'typescript'),('04','Call query and consume its messages','src/agent.ts','One query object can contain repeated model/tool interactions. The host forwards selected evidence and waits for a final result; finally closes the query and reads the resulting file.',extract(agent,'export async function runAgent','  } finally')+'\n  } finally {\n    conversation.close();\n    const after = await workspaceState();\n    emit({ type: "workspace", stage: "after", ...after, changed: after.source !== before.source });\n  }\n}','typescript'),('05','Separate assistant text from the final result','src/agent.ts','Assistant messages can contain text and tool requests. A successful final outcome requires success subtype with no error flag. A tool request alone is not proof that an edit was applied.',extract(agent,'export function projectMessage','export async function runAgent'),'typescript'),('06','Run independent Python regression checks','scripts/verify-utils.py','The test runner lives outside the agent working directory. It checks two ordinary calls and the two edge cases. This app chooses 0 for an empty average and an empty string for a missing user; those are explicit classroom contracts, not the only possible API design.',runner,'python'),('07','Print tool activity and verification evidence','src/sample.ts','The terminal prints SDK progress and the independent check count. It exits unsuccessfully if the file did not change or the post-run checks did not all pass. The web page shows both kinds of evidence separately.',sample,'typescript')]

document('/','Build a <em>bug-fixing agent.</em>','Follow Lesson 03: read utils.py, diagnose two crash bugs, apply edits, and verify the actual file.',
 '<div class="flow"><div><b>01 · Read</b><p>Inspect the buggy file</p></div><span>→</span><div><b>02 · Edit</b><p>Let the SDK apply changes</p></div><span>→</span><div><b>03 · Verify</b><p>Compare code and Python checks</p></div></div><section class="workspace"><article class="panel"><p class="eyebrow">LESSON 03 QUICKSTART</p><h2>Ask for a repair</h2><p id="configuration" class="meta">Checking local configuration…</p><form id="form"><label for="prompt">Prompt</label><textarea id="prompt" maxlength="2000" required></textarea><p class="meta">Model: <strong id="model">—</strong><br>Tools: Read · Edit · Glob<br>Permission: acceptEdits · Up to 12 turns</p><button class="primary" id="run" disabled>Fix utils.py →</button></form><p class="meta">Each click restores the buggy working copy before calling Claude. Only the disposable utils.py is editable. Per-run SDK budget: $0.50.</p></article><article class="panel"><p class="eyebrow">SDK OUTCOME AND HOST EVIDENCE</p><h2>Observe the run</h2><div class="stats"><div class="stat"><span>SDK status</span><strong id="status">Ready</strong></div><div class="stat"><span>Turns</span><strong id="turns">—</strong></div><div class="stat"><span>Estimated cost</span><strong id="cost">—</strong></div></div><div id="answer" aria-live="polite"></div><p class="meta">SDK session ID: <span id="session">—</span></p><details open><summary>Tool calls and selected SDK messages</summary><ol id="events"></ol></details></article></section><section class="diff-grid"><article class="panel"><h2>Before · buggy utils.py</h2><span class="check-badge" id="before-checks">Checking baseline…</span><pre><code class="language-python" id="before"></code></pre></article><article class="panel"><h2>After · actual agent edit</h2><span class="check-badge" id="after-checks">Not checked</span><pre><code class="language-python" id="after">The repaired file will appear after the run.</code></pre></article></section><section class="panel" id="verification"><p class="eyebrow">INDEPENDENT HOST REGRESSION CHECKS</p><h2 id="verdict">Waiting</h2><ul id="checks" class="checks"></ul><p>The host runs Python after the SDK finishes. The agent has no Bash tool and does not run these checks itself. A verified fix requires changed source and all four checks passing.</p></section><aside class="note contract"><strong>Explicit contract:</strong> average of [2,4,6] → 4; average of [] → 0; name of Ada → ADA; name of None → an empty string. These choices make this lab reproducible. Other applications may deliberately raise validation errors instead. The local path guard is not an operating-system sandbox. Wait for post-run verification before leaving the page.</aside>'+actions(('/learn.html','What you will learn →'),('/run.html','Configure and run →')), '<script type="module" src="/client.js"></script>')
document('/learn.html','Understand the <em>bug-fixing loop.</em>','Learn the concepts from the supplied Lesson 03 presentation, then inspect their evidence in a real run.',cards(learning)+'<section class="step"><h2>The lesson in six steps</h2><ol><li>Create the project directory.</li><li>Install the SDK and choose TypeScript.</li><li>Set the key in the launching shell.</li><li>Create the buggy Python file.</li><li>Write query with a prompt and edit options.</li><li>Run, inspect the real edits, and customise deliberately.</li></ol><p>This app uses TypeScript for the SDK host and Python for the file being repaired. Python is also required locally for the independent host checks.</p></section><section class="step"><h2>A useful distinction from the tools slide</h2><p><code>allowedTools</code> pre-approves operations; it does not by itself restrict the available tool set. This app sets <code>tools</code> too. Read-only experiments should remove Edit from tools, not just from allowedTools.</p><p>The UI shows assistant explanations and tool requests. It does not expose hidden model reasoning, and tool ordering is chosen by the model.</p></section>'+actions(('/','← Application lab'),('/run.html','Setup and run →')))
run='<section class="step"><span class="number">01</span><h2>Set up the project and install dependencies</h2><p>Use Node.js 24+ for this application, npm, Python 3.10+ for host checks, and an Anthropic API key. Git Bash may be required by the SDK on Windows. Keep optional npm dependencies enabled for the bundled runtime.</p>'+snippet('node --version\npython --version','powershell')+'<p>Clone the completed application:</p>'+snippet(clone,'powershell')+'<p>In the original presentations workspace, use <code>cd .\\agent-sdk\\lesson03-bug-fixing</code> and <code>npm ci</code>. The presentation’s from-scratch TypeScript setup is:</p>'+snippet(setup,'powershell')+'</section>'
run+='<section class="step"><span class="number">02</span><h2>Set your API key in the same shell</h2><p>Replace the safe placeholder locally, then run the sample from that PowerShell terminal:</p>'+snippet(shell,'powershell')+'<p>On macOS/Linux, use <code>export ANTHROPIC_API_KEY="your_api_key"</code> before <code>npm run sample</code>. The sample reads the process environment, not an automatic .env file. A new terminal needs its own assignment.</p><p>Optional explicit file loading:</p>'+snippet('if (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm run sample:env','powershell')+snippet(env,'dotenv')+'<p>A key already set in the shell takes precedence. Restart the web host after editing configuration. If Python is not called <code>python</code>, set PYTHON_BIN to its executable. On Windows, if needed, set <code>CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe</code>.</p></section>'
run+='<section class="step"><span class="number">03</span><h2>Create and understand the buggy file</h2>'+snippet(buggy,'python')+'<p>The fixture remains in <code>fixtures/utils.py</code>. Each run restores a disposable copy in <code>.runtime/bugfix-workspace/utils.py</code>. Initially, two normal checks pass and two edge cases fail with ZeroDivisionError and TypeError. The repaired file remains available locally after the run, until the next reset.</p></section>'
run+='<section class="step"><span class="number">04</span><h2>Write the agent options and run it</h2>'+snippet('const conversation = query({\n  prompt: "Review utils.py for bugs that would cause crashes. Fix any issues you find.",\n  options: {\n    cwd: WORKSPACE,\n    tools: ["Read", "Edit", "Glob"],\n    allowedTools: ["Read", "Edit", "Glob"],\n    permissionMode: "acceptEdits",\n  },\n});')+'<p>This short illustration shows the core options; the complete source adds the explicit contract, reset, path guard, limits and independent checks.</p>'+snippet('npm run sample:env\n# Web alternative:\nnpm start\n# Open http://127.0.0.1:3103','powershell')+'<p>Keep the web terminal open. Starting it makes no model call. Each submitted repair uses the API and may incur charges. Stop it with Ctrl+C.</p></section>'
run+='<section class="step"><span class="number">05</span><h2>Inspect the evidence</h2><ol><li>Confirm the default repair prompt and 2/4 baseline checks.</li><li>Click Fix utils.py once.</li><li>Observe Read and Edit requests; Glob may be used too.</li><li>Wait for the final SDK outcome and the host verification event.</li><li>Compare before/after code and confirm 4/4 checks plus a changed file.</li></ol><p>A successful SDK result with failing host checks is not a verified fix. The host test runner is outside the agent workspace and is never supplied as an editable target.</p></section>'
run+='<section class="step"><span class="number">06</span><h2>Customise and practise</h2><p>Try docstrings or type hints while preserving the four behaviour checks. A read-only experiment removes Edit from tools and changes the prompt to a bug report; its file should remain unchanged, so the UI should not claim a verified repair. The slides also discuss Bash and WebSearch as future extensions. They are not enabled in this app; adding them requires updating both the tool set and the local guard deliberately.</p>'+snippet('npm test\nnpm run build:client\npython scripts/build-pages.py','powershell')+'<p>If Python checks are unavailable, fix Python/PYTHON_BIN before spending an API call. If a runtime or Git Bash error occurs, keep optional dependencies installed and verify the Git Bash path. If this app already owns port 3103, a second start prints its URL; otherwise stop the other service or choose another PORT.</p></section>'
document('/run.html','Configure, run and <em>verify.</em>','Follow the presentation’s six-step quickstart and inspect an actual file repair.',run+actions(('/learn.html','← Learning goals'),('/','Open the repair lab →')))

lanes=['Student','Browser + host','Agent SDK','Claude API','utils.py']
arrows=[(0,1,'1. Request the repair'),(1,4,'2. Reset buggy copy; run baseline checks'),(1,2,'3. query(prompt, edit options)'),(2,3,'4. Send task and tool definitions'),(3,2,'5. Request Read or Glob'),(2,4,'6. Read the actual Python file'),(2,3,'7. Return file observations to Claude'),(3,2,'8. Request Edit for a crash bug'),(2,4,'9. Apply the permitted edit'),(3,2,'10. Finish the SDK turn sequence'),(2,1,'11. Yield text and final SDK result'),(1,4,'12. Read repaired file; run Python checks'),(1,0,'13. Show before/after and verified outcome')]
descriptions=['The prompt names utils.py and asks for crash fixes.','The host copies the original bugs into a disposable working directory and records the two expected failures.','The host sets Read/Edit/Glob availability, pre-approvals and acceptEdits, then creates one query.','The SDK talks to Claude; the API key remains in the launching process environment.','The model chooses how to inspect the target. Tool order is not a scripted fixture.','The SDK executes local discovery or reading; the host hook rejects paths outside this demo target.','The SDK sends the actual tool observations into its next model interaction.','The model requests an edit; the prompt and contract guide the intended behaviour.','The SDK applies the permitted edit to the disposable utils.py. The immutable fixture is unchanged.','The model may repeat read/edit interactions until it finishes or hits a limit.','The host receives the final result but still needs independent verification.','A trusted Python runner outside the agent directory checks normal and edge-case behaviour.','The student compares the changed source, SDK status and four regression outcomes.']
